import {emptyPermanentSlot,AREAS,IDS,investmentPreview,threatPreview,scoringPreview,smartPreview,alliedCount,winners} from './world.js';
import {renderIncomeEffects,incomeEffectNotice} from './event-income-ui.js';
import {powerFlag} from './power-identity.js';
const names={US:'美国',CN:'中国',EU:'欧盟',RU:'俄罗斯',neutral:'中立'};
const colors={US:'#52a9e7',CN:'#e56361',EU:'#e4bd43',RU:'#d2d8db',neutral:'#aaaaaa'};
const actorButton=id=>`<button data-player="${id}">切换到${names[id]}</button>`;
export function renderWorldRegion(s,region){const r=s.regions[region],a=AREAS[region];
 const slots=(list,kind)=>list.map((id,i)=>`<span class="influence-slot" style="border-color:${colors[id]||'#64748b'}"><b>${id?names[id]:kind==='permanent'&&(r.ignoredStartingSlots||[]).includes(i)?'停用起始槽':'空位'}</b>${id?`<button data-world-op="remove" data-kind="${kind}" data-index="${i}" aria-label="移除${names[id]}影响力">移除</button>`:''}${kind==='temporary'&&id===s.current?`<button data-world-op="reset" data-index="${i}">重置</button><button data-world-op="convert" data-index="${i}">转永久</button>`:''}</span>`).join('');
 return `<h3>永久影响力 ${r.permanent.filter(Boolean).length}/${a.slots-(r.ignoredStartingSlots||[]).length}</h3><div class="influence-slots">${slots(r.permanent,'permanent')}${slots(r.extraPermanent,'extraPermanent')}</div><button data-world-op="placePermanent" ${emptyPermanentSlot(r)<0?'disabled':''}>放置本方永久影响力 · +1分</button><h3>临时影响力 · 左侧最先被挤出</h3><div class="influence-slots">${slots(r.temporary,'temporary')||'暂无临时影响力'}</div><button data-world-op="placeTemporary">放置本方临时影响力 · +${r.temporary.length===a.temp.length?0:a.temp[r.temporary.length]}分</button><p class="minor">重置／转永久／移除仅按已处理的卡牌效果使用，不重新加分。普通放置的槽位分自动计入，行动费用仍需手动支付。</p><p>总影响力：${Object.entries(r.influence).map(([id,n])=>names[id]+' '+n).join(' · ')}</p><p>地区奖励 ${a.bonus.join('/')} · 利益地区玩家 ${a.interest.map(id=>names[id]).join('、')}</p><p>本方介入标记 ${r.engage[s.current]} <button data-engage-delta="-1">移除1个</button><button data-engage-delta="1">添加1个</button></p><p class="minor">介入标记增减用于记录已结算的牌面效果。</p>`;
}
export function threatSummary(s,player,defend=[]){
 const reports=Object.fromEntries(IDS.map(id=>[id,s.flow?.threatResults?.[id]||threatPreview(s,id,id===player?defend:[])]));
 const baseline=defend.length&&!s.flow?.threatResults?.[player]?threatPreview(s,player):null;
 const cell=(id,loss,region)=>{const changed=id===player&&baseline&&loss!==(region?baseline.rows.find(row=>row.region===region)?.loss||0:baseline.total);return `<td data-threat-player="${id}"${region?` data-threat-region="${region}"`:''} class="${id===player?'is-current ':''}${loss?'has-loss':'no-loss'}${changed?' is-changed':''}">${loss?'−'+loss:'0'}</td>`;};
 return `<table class="threat-loss-table" aria-label="各国地区扣分"><thead><tr><th scope="col">地区</th>${IDS.map(id=>`<th scope="col" class="${id===player?'is-current':''}">${powerFlag(id)}${s.flow?.threatDone?.includes(id)?'<small title="已结算" aria-label="已结算">✓</small>':''}</th>`).join('')}</tr></thead><tbody>${Object.entries(AREAS).map(([region,area])=>`<tr><th scope="row">${area.name}</th>${IDS.map(id=>cell(id,reports[id].rows.find(row=>row.region===region)?.loss||0,region)).join('')}</tr>`).join('')}</tbody><tfoot><tr><th scope="row">合计</th>${IDS.map(id=>cell(id,reports[id].total)).join('')}</tr></tfoot></table>`;
}
export function renderWorldAftermath(s,step){const f=s.flow;
 if(step==='投资回报'){if(f.pendingIncome)return renderIncomeEffects(s);const id=f.order[(f.investmentDone||[]).length],preview=investmentPreview(s,id);return `<b>投资回报 · ${names[id]}</b>${s.current!==id?actorButton(id):''}<p>已记录FDI的本轮收益：${preview.fdi}资金。</p><p>可选择撤回介入标记；每个标记获得该地区盟国数量×5资金。</p>${Object.entries(s.regions).filter(([,r])=>r.engage[id]>0).map(([region,r])=>`<label>${AREAS[region].name}（盟国${alliedCount(s,id,region)}，标记${r.engage[id]}）<input data-withdraw="${region}" type="number" min="0" max="${r.engage[id]}" value="0" step="1"></label>`).join('')}<p id="investment-preview">合计收益：${preview.total}资金</p><button id="resolve-investments" ${s.current!==id?'disabled':''}>领取收益并撤回所选标记</button>${incomeEffectNotice(s,id)}<p class="minor">请勿再手动领取上述基础收益；未接入的特殊卡牌修正仍需按牌面核对。</p>`;}
 if(step==='威胁结算'){const id=f.order[(f.threatDone||[]).length];return `<b>威胁扣分 · ${powerFlag(id)}</b>${s.current!==id?actorButton(id):''}<div id="threat-preview">${threatSummary(s,id)}</div>${Object.entries(AREAS).filter(([region,a])=>a.interest.includes(id)&&s.regions[region].engage[id]>0).map(([region])=>`<label><input type="checkbox" data-threat-defend="${region}"> ${AREAS[region].name}：消耗1介入，+${2*alliedCount(s,id,region)}防御</label>`).join('')}<button id="resolve-threat" ${s.current!==id?'disabled':''}>确认本方扣分</button>`;}
 if(step==='地区与多数计分'){const report=scoringPreview(s);return `<b>第${s.round}轮计分预览</b><p>永久槽填满才计算地区分；影响力相同先检查已生效的绝对权威，再比军队，仍并列取较低名次奖励。国家专属计分包含永久槽未填满的区域。</p><div class="score-scroll"><table class="score-table"><thead><tr><th>来源</th>${IDS.map(id=>`<th>${names[id]}</th>`).join('')}</tr></thead><tbody>${report.regions.map(r=>`<tr><td>${AREAS[r.region].name}${r.eligible?'':'（未满）'}</td>${IDS.map(id=>`<td>${r.points[id]}</td>`).join('')}</tr>`).join('')}${Object.entries(report.majority).map(([key,points])=>`<tr><td>${{money:'资金多数',armies:'军队多数',allies:'盟国多数'}[key]}</td>${IDS.map(id=>`<td>${points[id].vp}</td>`).join('')}</tr>`).join('')}<tr><td>国家能力</td>${IDS.map(id=>`<td>${report.national[id]}</td>`).join('')}</tr><tr><th>本次合计</th>${IDS.map(id=>`<th>${report.totals[id]}</th>`).join('')}</tr></tbody></table></div><button id="score-world">应用本次计分</button><p class="minor">含美国领先地区检查、俄罗斯利益地区军队奖励及末轮中国FDI网络。特殊卡牌额外得分仍需手动处理。目标、SP和未用资产在后续步骤结算。</p>`;}
 if(step==='Smart Power计分'){const points=smartPreview(s);return `<b>Smart Power计分</b><p>${IDS.map(id=>`${names[id]}：SP ${s.players[id].smart} → +${points[id]}分`).join(' · ')}</p><button id="score-smart">应用SP多数计分</button>`;}
 return null;
}
export function renderWinners(s){const ids=winners(s);return ids?`<p><b>${ids.length>1?'共同获胜':'获胜'}：${ids.map(id=>names[id]).join('、')}</b></p><p>已依次比较总分、末轮获得地区第一名奖励次数、地图总影响力。特殊卡牌和目标得分需先正确记录。</p>${s.finalAwards?`<p>已计入总分的终局奖励：${IDS.map(id=>`${names[id]} 未用资产 +${s.finalAwards[id].assets}、未用行政命令 +${s.finalAwards[id].executive}`).join('；')}。请勿重复领取。</p>`:''}`:'';}
